export function swiftStyleNative(
  style: OneNativeStyle | undefined
): OneNativeStyleNative | undefined {
  if (!style) return undefined
  const native: Record<string, unknown> = {}
  const sdkModifiers: [string, string][] = []
  for (const [name, value] of Object.entries(style)) {
    if (value === undefined) continue
    if (Object.hasOwn(sdkKinds, name)) {
      const kind = sdkKinds[name as keyof typeof sdkKinds]
      if (kind === 'record') {
        if (typeof value !== 'object' || value === null || Array.isArray(value))
          throw new Error(name + ' must be a record')
        const record = value as Record<string, unknown>
        const values = sdkRecords[name].map((argument) => {
          const item = record[argument.field]
          if (argument.optional && item === null) return null
          if (
            argument.kind === 'number' &&
            (typeof item !== 'number' || !Number.isFinite(item))
          )
            throw new Error(name + '.' + argument.field + ' must be finite')
          if (argument.kind === 'boolean' && typeof item !== 'boolean')
            throw new Error(name + '.' + argument.field + ' must be a boolean')
          if (
            (argument.kind === 'string' ||
              argument.kind === 'url' ||
              argument.kind === 'enum') &&
            typeof item !== 'string'
          )
            throw new Error(name + '.' + argument.field + ' must be a string')
          if (
            (argument.kind === 'stringArray' || argument.kind === 'stringSet') &&
            (!Array.isArray(item) || item.some((element) => typeof element !== 'string'))
          )
            throw new Error(name + '.' + argument.field + ' must be a string array')
          return argument.kind === 'stringArray' || argument.kind === 'stringSet'
            ? JSON.stringify(item)
            : String(item)
        })
        sdkModifiers.push([name, JSON.stringify(values)])
        continue
      }
      if (kind === 'number' && (typeof value !== 'number' || !Number.isFinite(value)))
        throw new Error(name + ' must be finite')
      if (
        kind === 'optionalNumber' &&
        value !== null &&
        (typeof value !== 'number' || !Number.isFinite(value))
      )
        throw new Error(name + ' must be finite or null')
      if (kind === 'boolean' && typeof value !== 'boolean')
        throw new Error(name + ' must be a boolean')
      if (kind === 'optionalBoolean' && value !== null && typeof value !== 'boolean')
        throw new Error(name + ' must be a boolean or null')
      if (kind === 'string' && typeof value !== 'string')
        throw new Error(name + ' must be a string')
      if (kind === 'url' && typeof value !== 'string')
        throw new Error(name + ' must be a URL string')
      if (kind === 'optionalURL' && value !== null && typeof value !== 'string')
        throw new Error(name + ' must be a URL string or null')
      if (kind === 'optionalEnum' && value !== null && typeof value !== 'string')
        throw new Error(name + ' must be a string or null')
      if (kind === 'optionalString' && value !== null && typeof value !== 'string')
        throw new Error(name + ' must be a string or null')
      if (
        kind.startsWith('event') &&
        kind !== 'eventValueString' &&
        typeof value !== 'function'
      )
        throw new Error(name + ' must be a callback')
      if (
        kind === 'eventValueString' &&
        (typeof value !== 'object' ||
          value === null ||
          typeof (value as { value?: unknown }).value !== 'string' ||
          typeof (value as { onChange?: unknown }).onChange !== 'function')
      )
        throw new Error(name + ' must be a string value and callback')
      if (
        (kind === 'bindingBoolean' || kind === 'bindingString') &&
        (typeof value !== 'object' ||
          value === null ||
          typeof (value as { onChange?: unknown }).onChange !== 'function' ||
          typeof (value as { value?: unknown }).value !==
            (kind === 'bindingBoolean' ? 'boolean' : 'string'))
      )
        throw new Error(name + ' must be a binding')
      sdkModifiers.push([
        name,
        kind === 'eventValueString'
          ? (value as { value: string }).value
          : kind.startsWith('event')
            ? ''
            : kind.startsWith('binding')
              ? String((value as { value: unknown }).value)
              : kind === 'optionalString' || kind === 'optionalURL'
                ? (JSON.stringify(value) as string)
                : String(value),
      ])
    } else if (colorFields.includes(name as (typeof colorFields)[number])) {
      native[name] = processColor(value as ColorValue) ?? undefined
    } else {
      native[name] = value
    }
  }
  if (sdkModifiers.length) native.sdkModifiers = JSON.stringify(sdkModifiers)
  return native as OneNativeStyleNative
}

export function dispatchSDKEvent(
  style: OneNativeStyle | undefined,
  name: string,
  value: string
): void {
  const modifier = (style as Record<string, unknown> | undefined)?.[name]
  const kind = sdkKinds[name as keyof typeof sdkKinds] as string | undefined
  if (kind === 'event') (modifier as (() => void) | undefined)?.()
  else if (kind === 'eventBoolean') {
    if (value !== 'true' && value !== 'false')
      throw new Error(name + ' emitted an invalid boolean')
    ;(modifier as ((value: boolean) => void) | undefined)?.(value === 'true')
  } else if (kind === 'eventNumber') {
    const number = Number(value)
    if (!Number.isFinite(number)) throw new Error(name + ' emitted an invalid number')
    ;(modifier as ((value: number) => void) | undefined)?.(number)
  } else if (kind === 'eventString')
    (modifier as ((value: string) => void) | undefined)?.(value)
  else if (kind === 'eventEnum') {
    if (!sdkEventCases[name].includes(value))
      throw new Error(name + ' emitted an invalid enum value')
    ;(modifier as ((value: string) => void) | undefined)?.(value)
  } else if (kind === 'eventEnumPair') {
    const pair: unknown = JSON.parse(value)
    if (
      !Array.isArray(pair) ||
      pair.length !== 2 ||
      pair.some((item) => typeof item !== 'string' || !sdkEventCases[name].includes(item))
    )
      throw new Error(name + ' emitted invalid enum values')
    ;(modifier as ((oldValue: string, newValue: string) => void) | undefined)?.(
      pair[0],
      pair[1]
    )
  } else if (kind === 'bindingBoolean')
    (modifier as { onChange: (value: boolean) => void } | undefined)?.onChange(
      value === 'true'
    )
  else if (kind === 'bindingString')
    (modifier as { onChange: (value: string) => void } | undefined)?.onChange(value)
  else if (kind === 'eventValueString')
    (modifier as { onChange: (value: string) => void } | undefined)?.onChange(value)
}
